fn fibonacci(n: usize) -> Vec<i32> {
    // Problem guarantees n >= 2.
    let mut ret: Vec<i32> = Vec::with_capacity(n);
    ret.push(0);
    ret.push(1);

    for i in 2..n {
        let a = ret[i - 1] as i64;
        let b = ret[i - 2] as i64;
        let next = a + b; // safe in i64
        ret.push(next as i32); // safe per problem guarantee
    }

    ret
}